// Discovery queue: area-level leads only, no invented street address, email or coordinates.
function lead(id,name,area,state,page,primary=true,curriculum=''){
 const url=`https://educationdestinationmalaysia.com/schools/${state==='Kuala Lumpur'?'kuala-lumpur':'selangor'}${page>1?'?page='+page:''}`;
 add(id,name,area,state,'',null,null,url,null,'',url,[],'','Discovery listing only. Verify current operating status, primary provision, campus address, subjects and application contact with the school.',curriculum);
 Object.assign(rows.at(-1),{discovery:true,primary,locationSource:url});
}
