// Follow-up research: 29 October 2026. Review dates apply only to the fields checked.
const followUpDate='2026-10-29';
function followUpSubjects(id,subjects,url,note){
 const s=rows.find(s=>s.id===id);
 Object.assign(s,{subjects,subjectSource:url,subjectChecked:followUpDate});
 delete s.subjectResearchSource;delete s.subjectResearchNote;
 if(note)s.notes=note;
}
